# ! [doc = " Type definitions for learning about the dependency formats of all upstream"] # ! [doc = " crates (rlibs/dylibs/oh my)."] # ! [doc = ""] # ! [doc = " For all the gory details, see the provider of the `dependency_formats`"] # ! [doc = " query."] use split_decls_genesis :: ourprelude :: * ; use rustc_data_structures :: fx :: FxIndexMap ; use rustc_hir :: def_id :: CrateNum ; use rustc_index :: IndexVec ; use rustc_macros :: { Decodable , Encodable , HashStable } ; use rustc_session :: config :: CrateType ; #[doc = " A list of dependencies for a certain crate type."] pub type DependencyList = IndexVec < CrateNum , Linkage > ; #[doc = " A mapping of all required dependencies for a particular flavor of output."] #[doc = ""] #[doc = " This is local to the tcx, and is generally relevant to one session."] pub type Dependencies = FxIndexMap < CrateType , DependencyList > ; #[derive (Copy , Clone , PartialEq , Debug , HashStable , Encodable , Decodable)] pub enum Linkage { NotLinked , IncludedFromDylib , Static , Dynamic , }